{
 "path": "/home/ubuntu/continual-arc-baselines/.workbench/runs/adhoc-openclawlearner-1790687872/attempts/0874d736f6374307823ec7507ddf4822/system/state/workspace/programs/task-d4c146e2.py",
 "content": "def transform(grid):
    # Objects consist of solid blocks/lines; sort by color sequence, stack motifs along diagonal.
    # Identify connected components and translate each component to staircase path, preserving shape.
    h,w=len(grid),len(grid[0])
    comps=[]; seen=set()
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((color,cells))
    # Each object is mapped into a diagonal arrangement in color order: block objects
    # follow a rising/falling staircase, while lines extend down/up in sequence.
    out=[[0]*w for _ in range(h)]
    # For this pattern, detect block dimensions and line dimensions; output objects ordered
    # from left to right along a diagonal staircase with step by one row and column.
    shapes=[]
    for color,cells in comps:
        minr=min(y for y,x in cells); minc=min(x for y,x in cells)
        rel=[(y-minr,x-minc) for y,x in cells]
        shapes.append((color,rel,len(set(y for y,x in rel)),len(set(x for y,x in rel))))
    # map positions using ascending source color/order: rows descend as objects progress;
    # infer layers: left side line first, then blocks, then right line. Their output anchors
    # are determined by the staircase packing: block 1 at (0,0), then subsequent starts
    # one row lower and one col further.
    shapes.sort(key=lambda z:min(x for y,x in next(c for co,c in comps if co==z[0])))
    # source horizontal order is already color objects. Place each object with cumulative
    # staircase offset based on earlier shape extents; output shown by demos has overlaps
    # at corners creating a connected colored ribbon.
    x0=y0=0
    for i,(color,rel,hh,ww) in enumerate(shapes):
        if len(rel)==1 or hh==1 or ww==1:
            # line objects retain direction but move onto diagonal edge
            if i==0: anchor=(0,0)
            else: anchor=(i-1,i-1)
        else:
            anchor=(i-1,i-1)
        for y,x in rel:
            yy,xx=anchor[0]+y,anchor[1]+x
            if 0<=yy<h and 0<=xx<w: out[yy][xx]=color
    return out
"
}

